func TestV2DynamicAggregateWireAndMetadata(t *testing.T) {
	integer, text := dynamicTestType(cqltype.TypeInt), dynamicTestType(cqltype.TypeText)
	list := dynamicTestMust(cqltype.ListType(integer))
