	scalarRejectLengths(t, Float32, cqltype.TypeFloat, 4)
	scalarRejectLengths(t, Float64, cqltype.TypeDouble, 8)
	scalarRejectLengths(t, CounterCodec, cqltype.TypeCounter, 8)
	scalarRejectLengths(t, DateCodec, cqltype.TypeDate, 4)
	scalarRejectLengths(t, TimeCodec, cqltype.TypeTime, 8)
	scalarRejectLengths(t, TimestampCodec, cqltype.TypeTimestamp, 8)
	scalarRejectLengths(t, UUIDCodec, cqltype.TypeUUID, 16)
	scalarRejectLengths(t, TimeUUIDCodec, cqltype.TypeTimeUUID, 16)
	if _, err := Bool.Decode(ScalarReader(t, cqltype.TypeBoolean, cqltype.Present, []byte{2})); err == nil {
		t.Fatal("accepted boolean 2")
	}
	for _, v := range []TimeOfDay{-1, TimeOfDay(nanosecondsPerDay)} {
		if _, err := scalarEncode(t, TimeCodec, cqltype.TypeTime, v); err == nil {
			t.Fatal("accepted invalid time")
