		var data [8]byte
		binary.BigEndian.PutUint64(data[:], uint64(v))
		if _, err := TimeCodec.Decode(ScalarReader(t, cqltype.TypeTime, cqltype.Present, data[:])); err == nil {
			t.Fatal("decoded invalid time")
