func TestParseAuthFrameDataIsCopied(t *testing.T) {
	t.Parallel()

	for _, op := range []frm.Op{frm.OpAuthChallenge, frm.OpAuthSuccess} {
		body := bodyOf(func(f *framer) { f.WriteBytes([]byte("token")) })
		got, err := parseOpBody(op, body)
		if err != nil {
			t.Fatal(err)
		}
		for i := range body {
			body[i] = 0xff
		}
		var data []byte
