		if v, e := s.Uint16(); v != 0x1020 || e != nil {
			t.Fatalf("u16 %d %v", v, e)
		}
		if v, e := s.Uint32(); v != 0x30405060 || e != nil {
			t.Fatalf("u32 %d %v", v, e)
		}
		if v, e := s.Uint64(); v != 0x708090a0b0c0d0e0 || e != nil {
			t.Fatalf("u64 %d %v", v, e)
