			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			cursor, err := RunStream(ctx, s, bound, step14DecoderError{cause}, StreamOptions{Options: Options{Idempotent: true}})
			if err != nil {
				t.Fatal(err)
