	defer bound.Close()
	cursor := codecTestMust(RunStream(ctx, s, bound, StreamOneColumn(StreamBlob), StreamOptions{Limits: StreamLimits{ReadAheadBytes: 1}}))
	spy.mu.Lock()
	for _, target := range spy.targets {
		if len(target) > 16 {
