	replicas := tokenRingReplicas{
		{InternalToken: int64Token(-100), InternalHosts: []*HostInfo{host0}},
		{InternalToken: int64Token(0), InternalHosts: []*HostInfo{host1}},
		{InternalToken: int64Token(100), InternalHosts: []*HostInfo{host2}},
