func TestTypedWritevBeyondPlatformVectorLimit(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()
	peer := make(chan net.Conn, 1)
	go func() {
		conn, err := listener.Accept()
		if err != nil {
			return
		}
		peer <- conn
	}()
	client, err := net.Dial("tcp", listener.Addr().String())
	if err != nil {
		t.Fatal(err)
	}
	defer client.Close()
	server := <-peer
	defer server.Close()
	var spans []wire.Span
	var expected []byte
	for i := 0; i < 2300; i++ {
		part := []byte{byte(i), byte(i >> 8), byte(i >> 16)}
		spans = append(spans, wire.Borrow(part))
		expected = append(expected, part...)
	}
	chain, _ := wire.NewChain(spans...)
	writer := &deadlineContextWriter{InternalW: client, InternalSemaphore: make(chan struct{}, 1), InternalQuit: make(chan struct{})}
	done := make(chan error, 1)
	go func() {
		n, err := writer.InternalWriteSpans(context.Background(), chain)
		if err == nil && n != chain.Len() {
			err = io.ErrShortWrite
		}
		done <- err
	}()
	received := make([]byte, len(expected))
	if _, err := io.ReadFull(server, received); err != nil {
		t.Fatal(err)
	}
	if err := <-done; err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(expected, received) {
		t.Fatal("writev truncated or reordered spans beyond vector limit")
	}
}

