func (p paramsPlan[P]) Encode(w *ParamWriter, value P) error {
	mark := w.builder.Mark()
	start := w.index
	for _, field := range p.ordered {
		if err := field.encode(w, value); err != nil {
			w.builder.Rollback(mark)
			w.index = start
			return err
		}
	}
	return nil
}

