func streamDeclarationCanReset[T any](decoder StreamDecoder[T]) bool {
	if decoder == nil {
		return false
	}
	if c, ok := decoder.(streamResetCapability); ok && !c.streamCanReset() {
		return false
	}
	_, ok := decoder.(StreamResetter[T])
	return ok
}

