func (c streamOneColumn[T]) Compile(columns cqltype.Columns) (StreamRowPlan[T], error) {
	if columns.Len() != 1 {
		return nil, cqltype.TypeValidation("stream row", "expected one column, got %d", columns.Len())
	}
	if c.decoder == nil {
		return nil, cqltype.TypeValidation("stream codec", "nil decoder")
	}
	p, e := compileStreamValuePlan(c.decoder, cqltype.ColumnSlice(columns)[0].Type)
	if e != nil {
		return nil, e
	}
	return streamOneColumnPlan[T]{p, columns}, nil
}

func (c streamOneColumn[T]) Reset(dst *T) {
	if dst != nil {
		resetStreamDeclaration(c.decoder, dst)
	}
}

func (p streamOneColumnPlan[T]) DecodeInto(r *StreamRowReader, dst *T) error {
	if dst == nil {
		return cqltype.TypeValidation("destination", "nil stream row destination")
	}
	if err := r.check(); err != nil {
		return err
	}
	if r.index != 0 || !r.matches(p.columns) {
		return r.shared.fail(cqltype.TypeValidation("stream metadata", "single column shape changed"))
	}
	if err := ReadStreamColumn(r, p.plan, dst); err != nil {
		return err
	}
	return r.RequireEnd()
}

func (p streamOneColumnPlan[T]) Reset(dst *T) {
	if dst != nil {
		p.plan.Reset(dst)
	}
}

