func (c recordDecoder[T]) CheckType(typ cqltype.DataType) error {
	perfCheckType()

	_, err := c.compileValueDecoder(typ)
	return err
}

func (c recordDecoder[T]) Clone(value T) T {
	return c.codec.Clone(value)
}

func (c recordDecoder[T]) Decode(r ValueReader) (T, error) {
	if c.plan == nil {
		bound, err := c.compileValueDecoder(r.Type())
		if err != nil {
			return *new(T), err
		}
		return bound.Decode(r)
	}
	slot := c.values.Get().(*T)
	err := c.DecodeInto(r, slot)
	value := *slot
	var zero T
	*slot = zero
	c.values.Put(slot)
	if err != nil {
		return zero, err
	}
	return value, nil
}

func (c recordDecoder[T]) compileValueDecoder(typ cqltype.DataType) (Decoder[T], error) {
	if c.kind == cqltype.TypeUDT {
		if err := checkUDTIdentity(typ, c.options); err != nil {
			return nil, err
		}
	}
	columns, err := recordColumns(typ, c.kind)
	if err != nil {
		return nil, err
	}
	if c.codec == nil {
		return nil, cqltype.TypeValidation("decoder", "nil tuple/UDT row decoder")
	}
	var plan RowPlan[T]
	if c.kind == cqltype.TypeUDT {
		plan, err = compileUDTRowDecoder(c.codec, columns, c.options)
	} else {
		plan, err = CompileRowPlan(c.codec, columns)
	}
	if err != nil {
		return nil, err
	}
	c.typ, c.columns, c.plan = typ, columns, plan
	c.readers = &sync.Pool{New: func() any { return new(recordReaderState) }}
	c.values = &sync.Pool{New: func() any { return new(T) }}
	return c, nil
}

