func (c recordEncoder[T]) CheckType(typ cqltype.DataType) error {
	perfCheckType()

	_, err := c.compileValueEncoder(typ)
	return err
}

func (c recordEncoder[T]) Encode(w *ValueWriter, value T) error {
	if c.plan == nil {
		bound, err := c.compileValueEncoder(w.Type())
		if err != nil {
			return err
		}
		return bound.Encode(w, value)
	}
	if !c.typ.Equal(w.Type()) {
		return cqltype.TypeValidation("type", "tuple/UDT identity or fields changed after compilation")
	}
	if err := w.payload(); err != nil {
		return err
	}
	params := NewParamWriter(w.builder, c.columns, false)
	params.ownBorrowed = w.ownBorrowed
	if err := c.plan.Encode(params, value); err != nil {
		return w.fail(err)
	}
	return w.fail(FinishParamWriter(params))
}

func (c recordEncoder[T]) compileValueEncoder(typ cqltype.DataType) (Encoder[T], error) {
	if c.kind == cqltype.TypeUDT {
		if err := checkUDTIdentity(typ, c.options); err != nil {
			return nil, err
		}
	}
	columns, err := recordColumns(typ, c.kind)
	if err != nil {
		return nil, err
	}
	if c.codec == nil {
		return nil, cqltype.TypeValidation("encoder", "nil tuple/UDT parameter encoder")
	}
	var plan ParamPlan[T]
	if c.kind == cqltype.TypeUDT {
		plan, err = compileUDTParamEncoder(c.codec, columns, c.options)
	} else {
		plan, err = CompileParamPlan(c.codec, columns)
	}
	if err != nil {
		return nil, err
	}
	c.typ, c.columns, c.plan = typ, columns, plan
	return c, nil
}

internal/codec/value_api.go::.DecodeValu.Source:
func DecodeValue[T any](decoder Decoder[T], value EncodedValue) (T, error) {
	var zero T
	if err := cqltype.ValidateDataType(value.typ); err != nil {
		return zero, err
	}
	if decoder == nil {
		return zero, cqltype.TypeValidation("decoder", "nil decoder")
	}
	compiled, err := compileValueDecoder(decoder, value.typ)
	if err != nil {
		return zero, err
	}
	if err := cqltype.CheckBytesAlive(value.body); err != nil {
		return zero, err
	}
	if value.state == cqltype.Unset {
		return zero, cqltype.TypeValidation("state", "unset cannot be decoded as a result")
	}
	return compiled.Decode(NewValueReader(value.typ, value.state, cqltype.BytesChain(value.body), cqltype.BytesLease(value.body)))
}

