internal/codec/value_io.go::.readFramedV.Source:
func readFramedValue(cursor *wire.Cursor, typ cqltype.DataType, lease *wire.Lease, allowUnset, nested bool) (ValueReader, error) {
	if err := cqltype.ValidateDataType(typ); err != nil {
		return ValueReader{}, err
	}
	if lease != nil && !lease.Alive() {
		return ValueReader{}, cqltype.ErrReleased
	}
	if cursor == nil {
		return ValueReader{}, cqltype.TypeValidation("cursor", "nil cursor")
	}
	checkpoint := *cursor
	fail := func(err error) (ValueReader, error) {
		*cursor = checkpoint
		return ValueReader{}, &cqltype.ProtocolError{Stage: "cell", Err: err}
	}
	prefix, err := cursor.Uint32()
	if err != nil {
		return fail(err)
	}
	length := int32(prefix)
	if length == -1 {
		return NewValueReader(typ, cqltype.Null, wire.Chain{}, lease), nil
	}
	if length == -2 && allowUnset {
		return NewValueReader(typ, cqltype.Unset, wire.Chain{}, lease), nil
	}
	if length < 0 {
		return fail(fmt.Errorf("invalid cell length %d", length))
	}
	var body wire.Chain
	if nested {
		body, err = cursor.TakeNested(int64(length))
	} else {
		body, err = cursor.Take(int64(length))
	}
	if err != nil {
		return fail(err)
	}
	return NewValueReader(typ, cqltype.Present, body, lease), nil
}

internal/codec/value_io.go::ValueWriter..Source:
func (w *ValueWriter) BorrowBytes(b []byte) error {
	if err := w.payload(); err != nil {
		return err
	}
	if w.ownBorrowed {
		b = append([]byte(nil), b...)
	}
	return w.fail(w.builder.Borrow(wire.Borrow(b)))
}

func (w *ValueWriter) BorrowString(s string) error {
	if err := w.payload(); err != nil {
		return err
	}
	if w.ownBorrowed {
		return w.fail(w.builder.Borrow(wire.Borrow([]byte(s))))
	}
	return w.fail(w.builder.Borrow(wire.BorrowString(s)))
}

func (w *ValueWriter) setState(state cqltype.CellState) error {
	if err := w.ready(); err != nil {
		return err
	}
	if w.wrote || w.state != cqltype.Present {
		return w.fail(cqltype.TypeValidation("value", "cell state was already written"))
	}
	if state == cqltype.Unset && !w.allowUnset {
		return w.fail(cqltype.TypeValidation("value", "unset is not permitted in this cell"))
	}
	w.state = state
	return nil
}

internal/cqltype/type.go::.UDTType.Source:
func UDTType(keyspace, name string, fields ...ColumnSpec) (DataType, error) {
	if keyspace == "" || name == "" {
		return DataType{}, TypeValidation("identity", "UDT keyspace and name must not be empty")
	}
	if len(fields) > math.MaxUint16 {
		return DataType{}, TypeValidation("fields", "UDT has too many fields")
	}
	seen := make(map[string]struct{}, len(fields))
	for i, c := range fields {
		if c.Name == "" {
			return DataType{}, TypeValidation("fields", "UDT field %d has no name", i)
		}
		if _, ok := seen[c.Name]; ok {
			return DataType{}, TypeValidation("fields", "duplicate UDT field %q", c.Name)
		}
		seen[c.Name] = struct{}{}
		if err := ValidateDataType(c.Type); err != nil {
			return DataType{}, fmt.Errorf("UDT field %q: %w", c.Name, err)
		}
	}
	return DataType{descriptor: &DataTypeDescriptor{Kind: TypeUDT, Keyspace: keyspace, Name: name, Fields: NewColumns(fields...)}}, nil
}

