func (p *InternalTypedConnPicker) Close() {
	p.InternalMu.Lock()
	if p.closed {
		p.InternalMu.Unlock()
		return
	}
	p.closed = true
	var all []*Conn
	for _, cs := range p.InternalConns {
		all = append(all, cs...)
	}
	all = append(all, p.InternalExcess...)
	all = append(all, p.retired...)
	p.retired = nil
	p.InternalConns = nil
	p.InternalExcess = nil
	p.InternalMu.Unlock()
	InternalCloseConns(all...)
}

