			h := SnapshotData(m).InternalHosts[i]
			if h.Enabled {
				t := p.target
				t.StrictShard = p.strict || t.StrictShard
				if t.ShardID.Set && (h.Shards == 0 || t.ShardID.Value >= h.Shards) {
					if t.StrictShard {
						return &InternalTargetPlan{}
					}
					t.ShardID = Option[uint32]{}
				}
