func ReadCompressedHeader(r io.Reader) (Header, error) {
	const headerSize = 5

	var headerBuf [headerSize + Crc24Size]byte
	if _, err := io.ReadFull(r, headerBuf[:]); err != nil {
		return Header{}, fmt.Errorf("gocql: failed to read compressed frame header, err: %w", err)
	}

	return DecodeHeader(headerBuf[:], true)
}

internal/segment/spans.go::.EncodeSpans.Source:
func EncodeSpans(payload wire.Chain, selfContained, compressed bool) (wire.Chain, error) {
	if payload.Len() > MaxPayloadSize {
		return wire.Chain{}, fmt.Errorf("gocql: segment payload exceeds %d", MaxPayloadSize)
	}
	originalLen := payload.Len()
	uncompressedLen := int64(0)
	if compressed {
		out, err := wirecompress.AppendLZ4(nil, payload)
		if err != nil {
			return wire.Chain{}, err
		}
		if len(out) > 0 && int64(len(out)) < originalLen {
			payload, _ = wire.NewChain(wire.Borrow(out))
			uncompressedLen = originalLen
		}
	}
	headerSize := HeaderSize(compressed)
	header := make([]byte, headerSize)
	fields := headerSize - Crc24Size
	packed := uint64(payload.Len())
	if compressed {
		packed |= uint64(uncompressedLen) << 17
		if selfContained {
			packed |= 1 << 34
		}
	} else if selfContained {
		packed |= 1 << 17
	}
	for i := 0; i < fields; i++ {
		header[i] = byte(packed >> (8 * i))
	}
	checksum := crc.Crc24(header[:fields])
	for i := 0; i < 3; i++ {
		header[fields+i] = byte(checksum >> (8 * i))
	}
	sum := crc32.ChecksumIEEE([]byte{0xfa, 0x2d, 0x55, 0xca})
	spans := []wire.Span{wire.Borrow(header)}
	_ = payload.Each(func(s wire.Span) error {
		sum = crc32.Update(sum, crc32.IEEETable, s.Bytes())
		spans = append(spans, s)
		return nil
	})
	trailer := make([]byte, 4)
	binary.LittleEndian.PutUint32(trailer, sum)
	spans = append(spans, wire.Borrow(trailer))
	return wire.NewChain(spans...)
}

internal/segment/spans.go::.ReadOwnedPay.Source:
func ReadOwnedPayload(r io.Reader, h Header, comp Compressor) (*wire.Lease, error) {
	if err := validatePayloadHeader(h, comp != nil); err != nil {
		return nil, err
	}
	payload := make([]byte, h.PayloadLen)
	if _, err := io.ReadFull(r, payload); err != nil {
		return nil, fmt.Errorf("gocql: failed reading segment payload: %w", err)
	}
	var trailer [4]byte
	if _, err := io.ReadFull(r, trailer[:]); err != nil {
		return nil, fmt.Errorf("gocql: failed reading segment CRC: %w", err)
	}
	if crc.Crc32(payload) != binary.LittleEndian.Uint32(trailer[:]) {
		return nil, fmt.Errorf("gocql: crc32 mismatch in segment payload")
	}
	if h.UncompressedLen != 0 {
		if comp == nil {
			return nil, fmt.Errorf("gocql: compressed segment without compressor")
		}
		decoded, err := comp.AppendDecompressed(make([]byte, 0, h.UncompressedLen), payload, uint32(h.UncompressedLen))
		if err != nil {
			return nil, err
		}
		if len(decoded) != h.UncompressedLen {
			return nil, fmt.Errorf("gocql: segment decompressed to %d bytes, expected %d", len(decoded), h.UncompressedLen)
		}
		payload = decoded
	}
	chain, _ := wire.NewChain(wire.Borrow(payload))
	return wire.NewLease(chain, nil), nil
}

internal/segment/units.go::UnitReader.Ne.Source:
func (r *UnitReader) Next() (Header, []byte, error) {
	if r.err != nil {
		return Header{}, nil, r.err
	}
	if r.closed {
		return r.fail(io.ErrClosedPipe)
	}
	if err := r.ctx.Err(); err != nil {
		return r.fail(err)
	}
	headerSize := HeaderSize(r.comp != nil)
	if _, err := io.ReadFull(r.source, r.framing[:headerSize]); err != nil {
		return r.fail(err)
	}
	h, err := DecodeHeader(r.framing[:headerSize], r.comp != nil)
	if err != nil {
		return r.fail(err)
	}
	if err := validatePayloadHeader(h, r.comp != nil); err != nil {
		return r.fail(err)
	}
	decoded := h.UncompressedLen
	if decoded == 0 {
		decoded = h.PayloadLen
	}
	if decoded > r.limits.MaxDecodedBytes || int64(h.PayloadLen+h.UncompressedLen)+unitFramingBytes > r.limits.MaxStorageBytes {
		return r.fail(ErrUnitLimit)
	}
	if err := r.ctx.Err(); err != nil {
		return r.fail(err)
	}
	if r.storage == nil {
		maxPayload := MaxPayloadSize
		if r.comp != nil {
			maxPayload *= 2
		}
		size := min(int64(maxPayload), r.limits.MaxStorageBytes-unitFramingBytes)
		r.storage = make([]byte, int(size))
	}
	payload := r.storage[:h.PayloadLen:h.PayloadLen]
	if _, err := io.ReadFull(r.source, payload); err != nil {
		return r.fail(err)
	}
	trailer := r.framing[CompressedHeaderSize : CompressedHeaderSize+Crc32Size]
	if _, err := io.ReadFull(r.source, trailer); err != nil {
		return r.fail(err)
	}
	if crc.Crc32(payload) != binary.LittleEndian.Uint32(trailer) {
		return r.fail(ErrUnitIntegrity)
	}
	if h.UncompressedLen != 0 {
		out := r.storage[h.PayloadLen : h.PayloadLen : h.PayloadLen+h.UncompressedLen]
		out, err = r.comp.AppendDecompressed(out, payload, uint32(h.UncompressedLen))
		if err != nil {
			return r.fail(err)
		}
		if len(out) != h.UncompressedLen || &out[0] != &r.storage[h.PayloadLen] {
			return r.fail(ErrDecoderStorage)
		}
		payload = out
	}
	if err := r.ctx.Err(); err != nil {
		return r.fail(err)
	}
	return h, payload, nil
}

internal/settings/v2_profiles.go::.Inter.Source:
func InternalValidateProfile(p Profile) error {
	if !InternalValidConsistency(p.Consistency) {
		return typeValidation("consistency", "invalid consistency")
	}
	if p.SerialConsistency.Set && p.SerialConsistency.Value != Serial && p.SerialConsistency.Value != LocalSerial {
		return typeValidation("serial consistency", "must be SERIAL or LOCAL_SERIAL")
	}
	if p.Timeout < 0 || p.PageTimeout < 0 {
		return typeValidation("timeout", "must not be negative")
	}
	if p.PageSize <= 0 {
		return typeValidation("page size", "must be positive")
	}
	if p.Prefetch < 0 || p.Prefetch > 1 {
		return typeValidation("prefetch", "must be zero or one")
	}
	return nil
}

internal/transport/v2_dial.go::.Internal.Source:
func InternalApplyV2SocketOptions(c net.Conn, config Config, network string) error {
	if network == "unix" || network == "unixpacket" {
		return nil
	}
	_, realTCP := c.LocalAddr().(*net.TCPAddr)
	unsupported := func(setting string) error {
		return &UnsupportedSettingError{Setting: setting, Reason: "raw TCP connection wrapper does not expose requested socket controls"}
	}
	if realTCP {
		noDelay, ok := c.(interface{ SetNoDelay(bool) error })
		if !ok {
			return unsupported("TCP_NODELAY")
		}
		if err := noDelay.SetNoDelay(config.NoDelay); err != nil {
			return err
		}
		keepalive, ok := c.(interface{ SetKeepAlive(bool) error })
		if !ok {
			return unsupported("TCP keepalive")
		}
		if err := keepalive.SetKeepAlive(config.SocketKeepalive > 0); err != nil {
			return err
		}
		if config.SocketKeepalive > 0 {
			period, ok := c.(interface{ SetKeepAlivePeriod(time.Duration) error })
			if !ok {
				return unsupported("TCP keepalive period")
			}
			if err := period.SetKeepAlivePeriod(config.SocketKeepalive); err != nil {
				return err
			}
		}
	}
	if config.ReceiveBuffer.Set {
		setter, ok := c.(interface{ SetReadBuffer(int) error })
		if !ok {
			return unsupported("receive buffer")
		}
		if err := setter.SetReadBuffer(config.ReceiveBuffer.Value); err != nil {
			return err
		}
	}
	if config.SendBuffer.Set {
		setter, ok := c.(interface{ SetWriteBuffer(int) error })
		if !ok {
			return unsupported("send buffer")
		}
		if err := setter.SetWriteBuffer(config.SendBuffer.Value); err != nil {
			return err
		}
	}
	if config.Linger.Set {
		setter, ok := c.(interface{ SetLinger(int) error })
		if !ok {
			return unsupported("linger")
		}
		if err := setter.SetLinger(int(config.Linger.Value / time.Second)); err != nil {
			return err
		}
	}
	if !realTCP && config.SocketKeepalive > 0 {
		return unsupported("TCP keepalive")
	}
	return nil
}

internal/transport/v2_dial.go::InternalV.Source:
func (d *InternalV2TLSHostDialer) DialHost(ctx context.Context, host *HostInfo) (*DialedHost, error) {
	return d.dial(ctx, host, -1, 0)
}

func (d *InternalV2TLSHostDialer) DialShard(ctx context.Context, host *HostInfo, shard, shards int) (*DialedHost, error) {
	return d.dial(ctx, host, shard, shards)
}

func (d *InternalV2TLSHostDialer) InternalSelectedTLS(ctx context.Context, host HostSnapshot) (*tls.Config, error) {
	c := d.InternalConfig.TLS
	if d.InternalConfig.TLSForHost != nil {
		v, err := d.InternalConfig.TLSForHost(ctx, InternalCloneV2HostSnapshot(host))
		if err != nil {
			return nil, err
		}
		if v != nil {
			c = v
		}
		if c == nil {
			return nil, typeValidation("TLSForHost", "TLS hook supplied no configuration and no inherited TLS configuration exists")
		}
	}
	if c != nil {
		c = cloneV2TLSConfig(c)
	}
	if d.InternalConfig.ClientRoutes != nil && d.InternalConfig.ClientRoutes.TLS && (c == nil || c.InsecureSkipVerify && c.VerifyConnection == nil && c.VerifyPeerCertificate == nil) {
		return nil, typeValidation("client routes TLS", "usable verified TLS required")
	}
	return c, nil
}

func (d *InternalV2TLSHostDialer) dial(ctx context.Context, host *HostInfo, shard, shards int) (*DialedHost, error) {
	epoch := implEndpoint.InternalHostInfoTransportEpoch(host)
	sharderEpoch := implEndpoint.InternalHostInfoSharderEpoch(host)
	snapshot, err := implEndpoint.SnapshotHost(host)
	if err != nil {
		return nil, err
	}
	if path, e := unixContact(d.InternalConfig); e != nil {
		return nil, e
	} else if path != "" {
		snapshot.Address = netip.AddrPort{}
		if d.InternalUnixHostID != nil {
			if local := d.InternalUnixHostID(); !local.IsEmpty() && !snapshot.ID.IsEmpty() && local != snapshot.ID {
				return nil, &UnsupportedSettingError{Setting: "Unix remote host", Reason: "one local socket cannot represent a remote node"}
			}
		}
		c, e := d.raw(ctx, DialTarget{Host: snapshot, Network: "unix", Address: path})
		if e != nil {
			return nil, e
		}
		return func() *DialedHost {
			opaqueStorageValue := new(DialedHost)
			opaqueStorageValue.Conn = c
			implEndpoint.DialedHostData(opaqueStorageValue).InternalTargetEpoch = epoch
			implEndpoint.DialedHostData(opaqueStorageValue).InternalSharderEpoch = sharderEpoch
			return opaqueStorageValue
		}(), nil
	}
	tlsConfig, err := d.InternalSelectedTLS(ctx, snapshot)
	if err != nil {
		return nil, err
	}
	address := net.JoinHostPort(host.ConnectAddress().String(), strconv.Itoa(host.Port()))
	logicalAddress := InternalLogicalV2TLSAddress(host)
	translated := implEndpoint.InternalHostInfoGetTranslatedConnectionInfo(host)
	if translated != nil && translated.CQL.IsValid() {
		address = translated.CQL.ToNetAddr()
	}
	if routes := d.InternalConfig.ClientRoutes; routes != nil && routes.SNIProxyAddress != "" {
		proxy, port, err := net.SplitHostPort(routes.SNIProxyAddress)
		if err != nil {
			proxy = routes.SNIProxyAddress
			_, port, _ = net.SplitHostPort(address)
		}
		resolver := &v2DNSResolver{InternalBase: d.InternalConfig.DNSResolver, InternalTimeout: d.InternalConfig.DNSTimeout}
		ips, err := resolver.LookupIPContext(ctx, proxy)
		if err != nil {
			return nil, err
		}
		if len(ips) == 0 {
			return nil, typeValidation("SNI proxy", "no resolved addresses")
		}
		address = net.JoinHostPort(ips[0].String(), port)
	}
	target := DialTarget{Host: snapshot, Network: "tcp", Address: address}
	if d.InternalConfig.LocalAddress.IsValid() {
		target.LocalAddress = netip.AddrPortFrom(d.InternalConfig.LocalAddress, 0)
	}
	var c net.Conn
	var selectedShard Option[uint32]
	if shards > 0 && d.InternalConfig.Pool.ShardAwarePort && d.InternalConfig.Pool.ConnectionsPerHost == 0 {
		if shard < 0 || shard >= shards {
			return nil, typeValidation("shard", "target out of range")
		}
		endpoint := ""
		if translated != nil {
			if tlsConfig != nil && translated.ShardAwareTLS.IsValid() {
				endpoint = translated.ShardAwareTLS.ToNetAddr()
			} else if tlsConfig == nil && translated.ShardAware.IsValid() {
				endpoint = translated.ShardAware.ToNetAddr()
			}
		}
		if endpoint != "" {
			for port := int(d.InternalConfig.Pool.SourcePortStart); port <= int(d.InternalConfig.Pool.SourcePortEnd); port++ {
				if port%shards != shard {
					continue
				}
				attempt := target
				attempt.Address = endpoint
				attempt.ShardID = Option[uint32]{Value: uint32(shard), Set: true}
				ip := d.InternalConfig.LocalAddress
				if !ip.IsValid() {
					ip = netip.IPv4Unspecified()
					if snapshot.Address.Addr().Is6() {
						ip = netip.IPv6Unspecified()
					}
				}
				attempt.LocalAddress = netip.AddrPortFrom(ip, uint16(port))
				c, err = d.raw(ctx, attempt)
				if err == nil {
					selectedShard = attempt.ShardID
					break
				}
				if ctx.Err() != nil {
					return nil, ctx.Err()
				}
				if !InternalIsLocalAddrInUseErr(err) {
					break
				}
			}
		}
	}
	if c == nil {
		c, err = d.raw(ctx, target)
		if err != nil {
			return nil, err
		}
	}
	if tlsConfig != nil && tlsConfig.ServerName == "" && !snapshot.Address.IsValid() {
		c.Close()
		return nil, typeValidation("TLS identity", "missing logical host name")
	}
	result, err := WrapTLS(ctx, c, logicalAddress, tlsConfig)
	if err != nil {
		return nil, err
	}
	implEndpoint.DialedHostData(result).InternalShardTarget = selectedShard
	implEndpoint.DialedHostData(result).InternalTargetEpoch = epoch
	implEndpoint.DialedHostData(result).InternalSharderEpoch = sharderEpoch
	implEndpoint.DialedHostData(result).InternalValidateTarget = func(ctx context.Context) error {
		current, err := implEndpoint.SnapshotHost(host)
		if err != nil {
			return err
		}
		if current.ID != snapshot.ID || current.Address != snapshot.Address || current.Datacenter != snapshot.Datacenter || current.Rack != snapshot.Rack || InternalLogicalV2TLSAddress(host) != logicalAddress {
			return typeValidation("dial target generation", "host identity/endpoint changed during opening")
		}
		if d.InternalConfig.TLSForHost != nil {
			now, err := d.InternalSelectedTLS(ctx, current)
			if err != nil {
				return err
			}
			if !InternalEqualV2TLSConfig(tlsConfig, now) {
				return typeValidation("dial target generation", "TLS/SNI target changed during opening")
			}
		}
		return nil
	}
	return result, nil
}

internal/transport/v2_stream_transport.g.Source:
func InternalCheckedStreamLimits(l StreamLimits) (StreamLimits, error) {
	if l.MaxMetadataBytes < 0 || l.ReadAheadBytes < 0 || l.DiscardBytes < 0 || l.MaxTransformBytes < 0 {
		return l, typeValidation("stream limits", "negative budget")
	}
	if l.MaxMetadataBytes == 0 {
		l.MaxMetadataBytes = 1 << 20
	}
	if l.ReadAheadBytes == 0 {
		l.ReadAheadBytes = 32 << 10
	}
	if l.DiscardBytes == 0 {
		l.DiscardBytes = 32 << 10
	}
	if l.MaxTransformBytes == 0 {
		l.MaxTransformBytes = segment.DefaultUnitStorageBytes
	}
	if l.MaxTransformBytes < 16 {
		return l, typeValidation("stream limits", "transform budget below framing size")
	}
	return l, nil
}

func InternalDecodeStreamRow[R any](response *InternalStreamResponse, plan StreamRowPlan[R], dst *R) (ok bool, err error) {
	if response == nil {
		return false, typeValidation("stream response", "nil response")
	}
	pageCtx := response.InternalCtx
	if pageCtx == nil {
		return false, typeValidation("stream context", "response has no page context")
	}
	err = response.reservation.InternalWithIO(pageCtx, func() error {
		if response.InternalTerminal {
			return nil
		}
		if response.InternalIndex == response.InternalRowCount && response.reservation.InternalComplete {
			response.InternalTerminal = true
			return nil
		}
		if dst == nil {
			return typeValidation("destination", "nil stream destination")
		}
		if response.InternalReader == nil || plan == nil {
			return typeValidation("stream plan", "metadata/plan not installed")
		}
		if response.InternalIndex == response.InternalRowCount {
			if err := response.InternalBody.RequireEnd(); err != nil {
				return err
			}
			if err := response.reservation.InternalFinishResponse(); err != nil {
				return err
			}
			response.InternalTerminal = true
			return nil
		}
		codec.BeginStreamRow(response.InternalReader)
		plan.Reset(dst)
		if err := plan.DecodeInto(response.InternalReader, dst); err != nil {
			return err
		}
		if err := response.InternalReader.RequireEnd(); err != nil {
			return err
		}
		response.InternalIndex++
		ok = true
		// Exact final framing is checked before publication of the final row.
		if response.InternalIndex == response.InternalRowCount {
			if err := response.InternalBody.RequireEnd(); err != nil {
				return err
			}
			if err := response.reservation.InternalFinishResponse(); err != nil {
				return err
			}
			response.InternalTerminal = true
		}
		return nil
	})
	if err != nil {
		ok = false
		response.reservation.InternalClose(false)
	}
	return ok, err
}

func (c *Conn) InternalDispatchEventOwned(event frame, release func()) error {
	c.eventMu.Lock()
	defer c.eventMu.Unlock()
	reject := func(err error) error {
		if release != nil {
			release()
		}
		return err
	}
	if c.InternalHooks == nil {
		return reject(nil)
	}
	if c.eventsClosed || c.InternalCtx.Err() != nil {
		return reject(ErrClosed)
	}
	c.eventOnce.Do(func() {
		c.eventQueue = make(chan InternalConnEvent, 32)
		c.InternalMu.Lock()
		c.eventDone = make(chan struct{})
		done := c.eventDone
		c.InternalMu.Unlock()
		coordinator := c.InternalHooks
		if !coordinator.InternalStartConnectionWorker(func() {
			defer close(done)
			defer func() {
				c.eventMu.Lock()
				defer c.eventMu.Unlock()
				c.eventsClosed = true
				for {
					select {
					case e := <-c.eventQueue:
						if e.release != nil {
							e.release()
						}
					default:
						return
					}
				}
			}()
			for {
				select {
				case <-coordinator.InternalConnectionWorkersDone():
					return
				case <-c.InternalCtx.Done():
					return
				case e := <-c.eventQueue:
					retained := coordinator.InternalHandleConnectionEvent(c.InternalCtx, e.value, e.release)
					if !retained && e.release != nil {
						e.release()
					}
				}
			}
		}) {
			c.eventsClosed = true
			close(done)
		}
	})
	if c.eventsClosed {
		return reject(ErrClosed)
	}
	select {
	case c.eventQueue <- InternalConnEvent{event, release}:
		return nil
	default:
		return reject(&ProtocolError{Stage: "event queue", Err: errors.New("bounded event dispatch overflow")})
	}
}

func (c *Conn) InternalWaitEventDispatch() {
	c.InternalMu.Lock()
	done := c.eventDone
	c.InternalMu.Unlock()
	if done != nil {
		<-done
	}
}

func (r *InternalExclusiveConn) InternalExchange(ctx context.Context, request *attemptRequest) (response *InternalStreamResponse, err error) {
	err = r.InternalWithIO(ctx, func() error {
		var pending *streamMetadataCursor
		defer func() {
			if pending != nil {
				pending.Release()
			}
		}()
		if request == nil {
			return typeValidation("stream request", "nil attempt")
		}
		if !r.InternalComplete {
			return &ProtocolError{Stage: "stream exchange", Err: errors.New("prior response incomplete")}
		}
		if r.InternalLimits.MaxMetadataBytes == 0 {
			if err := r.InternalInitStream(StreamLimits{}); err != nil {
				return err
			}
		}
		if request.Lease != nil {
			if !request.Lease.Retain() {
				return ErrReleased
			}
			defer request.Lease.Release()
		}
		owners := make([]*wire.Lease, 0, len(request.Payload))
		defer func() {
			for _, o := range owners {
				o.Release()
			}
		}()
		for _, e := range request.Payload {
			if e.Value.Valid && cqltype.BytesLease(e.Value.Value) != nil {
				if !cqltype.BytesLease(e.Value.Value).Retain() {
					return ErrReleased
				}
				owners = append(owners, cqltype.BytesLease(e.Value.Value))
			}
		}
		packet, err := r.InternalConn.InternalBuildTypedRequest(request, r.InternalStream)
		if err != nil {
			return err
		}
		writer, ok := r.InternalConn.InternalW.(spanContextWriter)
		if !ok {
			return &StreamCapabilityError{Protocol: int(r.InternalConn.InternalVersion), Reason: "writer lacks span support"}
		}
		if err := r.watchIOContext(ctx); err != nil {
			return err
		}
		r.InternalComplete = false
		written, err := writer.InternalWriteSpans(ctx, packet)
		if err != nil {
			return runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: err, InternalPotentiallyExecuted: written > 0})
		}
		for {
			if r.InternalUnits != nil {
				r.InternalUnits.beginFrame()
			}
			limits := r.InternalConn.typedProtocolLimits()
			header, body, err := frm.ReadStreamEnvelope(ctx, r.receiveSource(), r.InternalConn.InternalVersion, wire.StreamLimits{MaxBytes: min(limits.MaxFrameBytes, limits.MaxDecompressedBytes), MaxDepth: limits.MaxMetadataDepth + 2, DiscardBytes: r.InternalLimits.DiscardBytes}, r.InternalConn.typedResponseExtensionFlags())
			if err != nil {
				return err
			}
			cursor := &streamMetadataCursor{Scope: body, Budget: r.InternalMetadataBudget}
			pending = cursor
			p := &typedParser{Cursor: cursor, Proto: r.InternalConn.InternalVersion, MetadataID: r.InternalConn.InternalTracksResultMetadataID(), MaxDepth: limits.MaxMetadataDepth}
			info := p.StreamExtensions(header)
			if p.Err != nil {
				return p.Err
			}
			if header.Op == frm.OpEvent {
				event := p.StreamEvent(header)
				if p.Err != nil {
					return p.Err
				}
				if err := body.RequireEnd(); err != nil {
					return err
				}
				if r.InternalUnits != nil {
					if err := r.InternalUnits.endFrame(); err != nil {
						return err
					}
				}
				r.InternalComplete = true
				pending = nil
				r.InternalComplete = false
				if err := r.InternalConn.InternalDispatchEventOwned(event, cursor.Release); err != nil {
					return err
				}
				r.InternalComplete = false
				continue
			}
			if header.Stream != r.InternalStream {
				return &ProtocolError{Stage: "stream response", Err: fmt.Errorf("unexpected stream %d", header.Stream)}
			}
			if header.Op == frm.OpError {
				serverErr := p.ServerError(header, r.InternalConn.InternalFramers.InternalDefaults.rateLimitingErrorCode)
				if p.Err != nil {
					return p.Err
				}
				if err := body.RequireEnd(); err != nil {
					return err
				}
				if err := r.InternalFinishResponse(); err != nil {
					return err
				}
				response = &InternalStreamResponse{InternalCtx: ctx, reservation: r, InternalBody: body, InternalBudget: cursor, InternalInfo: info, InternalTerminal: true}
				pending = nil
				return serverErr
			}
			if header.Op != frm.OpResult {
				return &ProtocolError{Stage: "stream response", Err: fmt.Errorf("unexpected opcode %d", header.Op)}
			}
			result := &InternalStreamResponse{InternalCtx: ctx, reservation: r, InternalBody: body, InternalBudget: cursor, InternalInfo: info, InternalKind: p.I32()}
			switch result.InternalKind {
			case frm.ResultKindRows:
				result.InternalColumns, result.InternalColumnCount = p.MetadataFields(&result.InternalMetadata, false, 0)
				result.InternalRowCount = int32(p.I32())
				if result.InternalRowCount < 0 {
					return &ProtocolError{Stage: "stream rows", Err: wire.ErrLength}
				}
				if _, err := wire.CheckProduct(int64(result.InternalRowCount), int64(result.InternalColumnCount), body.Remaining()/4); err != nil {
					return err
				}
			case frm.ResultKindVoid:
				if err := body.RequireEnd(); err != nil {
					return err
				}
				if err := r.InternalFinishResponse(); err != nil {
					return err
				}
				result.InternalTerminal = true
			default:
				return &StreamCapabilityError{Protocol: int(r.InternalConn.InternalVersion), Reason: "streaming execution requires ROWS or VOID result"}
			}
			if p.Err != nil {
				return p.Err
			}
			response = result
			pending = nil
			return nil
		}
	})
	if err != nil && !r.InternalComplete {
		r.InternalClose(false)
	}
	return response, err
}

func (r *InternalExclusiveConn) InternalFinishResponse() error {
	if r.InternalUnits != nil {
		if err := r.InternalUnits.endFrame(); err != nil {
			return err
		}
	}
	r.InternalComplete = true
	r.stopIOContext()
	return nil
}

func (r *InternalExclusiveConn) InternalWithIO(ctx context.Context, fn func() error) error {
	if ctx == nil {
		return typeValidation("stream context", "nil context")
	}
	if r.InternalClosing.Load() {
		return ErrClosed
	}
	r.active.Lock()
	defer r.active.Unlock()
	if r.InternalClosing.Load() || r.closed || r.InternalConn.InternalCtx.Err() != nil {
		return ErrClosed
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	err := fn()
	if r.InternalClosing.Load() {
		if cause := r.cancellationCause(); cause != nil {
			return cause
		}
	}
	if err == nil {
		err = ctx.Err()
	}
	if err == nil {
		err = r.InternalCtx.Err()
	}
	return err
}

func (r *InternalExclusiveConn) receiveSource() io.Reader {
	if r.InternalUnits != nil {
		return r.InternalUnits
	}
	return r.InternalConn.InternalR
}

func (r *InternalStreamResponse) InternalWorkingStorageBytes() int64 {
	if r == nil {
		return 0
	}
	n := r.InternalBody.WorkingStorageBytes()
	if r.reservation.InternalMetadataBudget != nil {
		n += r.reservation.InternalMetadataBudget.Bytes()
	}
	n += codec.InternalStreamReaderWorkingStorageBytes(r.InternalReader)
	if r.reservation.InternalUnits != nil {
		n += r.reservation.InternalUnits.InternalUnits.StorageBytes()
	}
	if reader, ok := r.reservation.InternalConn.InternalR.(*InternalConnReader); ok && reader.InternalR != nil {
		n += int64(reader.InternalR.Size())
	}
	return n
}

internal/transport/v2_transport.go::Conn.Source:
func (c *Conn) InternalBuildTypedRequest(req *attemptRequest, stream int) (wire.Chain, error) {
	return c.nativeProtocol().BuildTypedRequest(req, stream)
}

func (c *Conn) InternalExecuteTyped(ctx context.Context, req *attemptRequest) (*InternalResponsePage, error) {
	if err := c.beginShared(ctx); err != nil {
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: err})
	}
	defer c.endShared()
	if err := ctx.Err(); err != nil {
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: err})
	}
	if req == nil {
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: fmt.Errorf("gocql: nil typed attempt")})
	}
	if req.Lease != nil {
		if !req.Lease.Retain() {
			return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: ErrReleased})
		}
		// The writer's synchronous completion is an explicit input lifetime boundary.
		defer req.Lease.Release()
	}
	// Custom payload views can belong to a previously received page. Each
	// accepted attempt holds those leases just like canonical bound values.
	var payloadOwners []*wire.Lease
	defer func() {
		for _, owner := range payloadOwners {
			owner.Release()
		}
	}()
	for _, entry := range req.Payload {
		if entry.Value.Valid && cqltype.BytesLease(entry.Value.Value) != nil {
			owner := cqltype.BytesLease(entry.Value.Value)
			if !owner.Retain() {
				return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: ErrReleased})
			}
			payloadOwners = append(payloadOwners, owner)
		}
	}
	stream, ok := c.InternalStreams.GetStream()
	if !ok {
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: ErrNoStreams})
	}
	call := InternalGetCallReq(stream)
	call.InternalTyped = true
	if c.InternalStreamObserver != nil {
		call.streamObserverContext = c.InternalStreamObserver.StreamContext(ctx)
	}
	if err := c.addCall(call); err != nil {
		c.InternalStreams.Clear(stream)
		call.finishExec()
		InternalPutCallReq(call)
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: err})
	}
	var stopWaiting, releaseStream, recycleCall bool
	var closeErr error
	defer func() {
		if closeErr != nil {
			c.InternalCloseWithError(closeErr)
		}
	}()
	defer func() {
		if stopWaiting {
			close(call.InternalTimeout)
		}
		call.finishExec()
		if releaseStream {
			c.releaseStream(call)
		}
		if recycleCall {
			InternalPutCallReq(call)
		}
	}()
	failBeforeWrite := func(err error) (*InternalResponsePage, error) {
		stopWaiting = true
		if c.InternalRemoveCallIfOpen(stream) {
			releaseStream = true
			recycleCall = true
		}
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: err})
	}
	packet, err := c.InternalBuildTypedRequest(req, stream)
	if err != nil {
		return failBeforeWrite(err)
	}
	writer, ok := c.InternalW.(spanContextWriter)
	if !ok {
		return failBeforeWrite(fmt.Errorf("gocql: connection writer does not support immutable spans"))
	}
	if call.streamObserverContext != nil {
		call.streamObserverContext.StreamStarted(ObservedStream{Host: c.InternalHost})
	}
	n, err := writer.InternalWriteSpans(ctx, packet)
	if err != nil {
		stopWaiting = true
		if n == 0 && (errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded)) {
			if c.InternalRemoveCallIfOpen(stream) {
				releaseStream = true
				recycleCall = true
			}
		} else {
			closeErr = err
		}
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: err, InternalPotentiallyExecuted: n > 0})
	}
	var timeoutCh <-chan time.Time
	if req.Timeout > 0 {
		if call.timer == nil {
			call.timer = time.NewTimer(req.Timeout)
		} else {
			if !call.timer.Stop() {
				select {
				case <-call.timer.C:
				default:
				}
			}
			call.timer.Reset(req.Timeout)
		}
		timeoutCh = call.timer.C
	}
	select {
	case resp := <-call.InternalResp:
		stopWaiting = true
		if resp.removedFromCalls {
			releaseStream = true
			recycleCall = true
		}
		if resp.InternalErr != nil {
			return resp.InternalPage, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: resp.InternalErr, InternalPotentiallyExecuted: true})
		}
		return resp.InternalPage, nil
	case <-timeoutCh:
		stopWaiting = true
		if c.markOrphan(call) {
			closeErr = InternalErrOrphanBudget
		}
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: ErrTimeoutNoResponse, InternalPotentiallyExecuted: true, InternalTimeout: req.Timeout, InternalInFlight: c.InternalStreams.InUse()})
	case <-ctx.Done():
		stopWaiting = true
		if c.markOrphan(call) {
			closeErr = InternalErrOrphanBudget
		}
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: ctx.Err(), InternalPotentiallyExecuted: true, InternalTimeout: req.Timeout, InternalInFlight: c.InternalStreams.InUse()})
	case <-c.InternalCtx.Done():
		stopWaiting = true
		return nil, runtimeerrors.NewQueryError(runtimeerrors.QueryErrorState{InternalErr: ErrConnectionClosed, InternalPotentiallyExecuted: true})
	}
}

func (c *Conn) typedProtocolLimits() ProtocolLimits {
	limits := ProtocolLimits{MaxFrameBytes: frm.MaxFrameSize, MaxDecompressedBytes: frm.MaxFrameSize, MaxMetadataDepth: 64}
	if c.InternalCfg != nil {
		configured := c.InternalCfg.TypedLimits
		if configured.MaxFrameBytes > 0 {
			limits.MaxFrameBytes = configured.MaxFrameBytes
		}
		if configured.MaxDecompressedBytes > 0 {
			limits.MaxDecompressedBytes = configured.MaxDecompressedBytes
		}
		if configured.MaxMetadataDepth > 0 {
			limits.MaxMetadataDepth = min(configured.MaxMetadataDepth, 128)
		}
	}
	return limits
}

internal/transport/v2_transport_writer.g.Source:
func (w *InternalDeadlineContextWriter) InternalWriteSpans(ctx context.Context, chain wire.Chain) (int64, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	select {
	case <-ctx.Done():
		return 0, ctx.Err()
	case <-w.InternalQuit:
		return 0, ErrConnectionClosed
	case w.InternalSemaphore <- struct{}{}:
	}
	defer func() { <-w.InternalSemaphore }()
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if err := w.InternalW.SetWriteDeadline(InternalEffectiveWriteDeadline(w.InternalTimeout.Load())); err != nil {
		return 0, err
	}

	var spans net.Buffers
	_ = chain.Each(func(s wire.Span) error { spans = append(spans, s.Bytes()); return nil })
	n, err := InternalWriteSpanBuffers(w.InternalW, spans)
	if err == nil && n != chain.Len() {
		err = io.ErrShortWrite
	}
	return n, err
}

func (w *InternalWriteCoalescer) InternalWriteSpans(ctx context.Context, chain wire.Chain) (int64, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	resultChan := InternalWriteResultChanPool.Get().(chan InternalWriteResult)
	req := InternalWriteRequest{chain: chain, resultChan: resultChan}
	select {
	case <-ctx.Done():
		InternalWriteResultChanPool.Put(resultChan)
		return 0, ctx.Err()
	case <-w.InternalQuit:
		InternalWriteResultChanPool.Put(resultChan)
		return 0, ErrConnectionClosed
	case w.InternalWriteCh <- req:
	}
	if w.InternalTestEnqueuedHook != nil {
		w.InternalTestEnqueuedHook()
	}
	// Cancellation after admission must join the writer before releasing input.
	result := <-resultChan
	InternalWriteResultChanPool.Put(resultChan)
	return result.InternalWritten, result.InternalErr
}

internal/wire/builder.go::Builder.Borrow.Source:
func (b *Builder) Borrow(s Span) error {
	if s.Len() == 0 {
		return nil
	}
	n, err := addLength(b.len, s.Len())
	if err != nil {
		return err
	}
	b.parts = append(b.parts, builderPart{span: s})
	b.currentPart = -1
	b.len = n
	return nil
}

internal/wire/builder.go::Builder.Freeze.Source:
func (b *Builder) Freeze() (Chain, error) {
	var c Chain
	if len(b.parts) > 0 {
		c.head = b.parts[0].span
		c.len = b.len
		if len(b.parts) > 1 {
			c.tail = make([]indexedSpan, len(b.parts)-1)
			end := int64(c.head.Len())
			for i := 1; i < len(b.parts); i++ {
				end += int64(b.parts[i].span.Len())
				c.tail[i-1] = indexedSpan{span: b.parts[i].span, end: end}
			}
		}
	}
	clear(b.parts)
	b.parts = b.parts[:0]
	b.slab = nil
	b.used = 0
	b.currentPart = -1
	b.len = 0
	b.generation++
	b.sequence = 0
	b.invalid = b.invalid[:0]
	return c, nil
}

internal/wire/builder.go::Builder.PatchU.Source:
func (b *Builder) PatchUint32(m Mark, v uint32) error {
	if !b.valid(m) {
		return ErrInvalidMark
	}
	if b.len-m.offset < 4 {
		return ErrBounds
	}
	off := m.offset
	first := 0
	for off >= int64(b.parts[first].span.Len()) {
		off -= int64(b.parts[first].span.Len())
		first++
	}
	remaining := 4
	for i, skip := first, int(off); remaining > 0; i, skip = i+1, 0 {
		part := b.parts[i]
		if !part.owned {
			return ErrBorrowedPatch
		}
		remaining -= min(remaining, part.span.Len()-skip)
	}
	var data [4]byte
	binary.BigEndian.PutUint32(data[:], v)
	written := 0
	for i, skip := first, int(off); written < len(data); i, skip = i+1, 0 {
		written += copy(b.parts[i].span.data[skip:], data[written:])
	}
	return nil
}

internal/wire/builder.go::Builder.Rollba.Source:
func (b *Builder) Rollback(m Mark) {
	if !b.valid(m) {
		return
	}
	if m.sequence < b.sequence {
		b.invalid = append(b.invalid, invalidMarks{after: m.sequence, through: b.sequence})
	}
	remaining := m.offset
	keep := 0
	for keep < len(b.parts) && remaining > 0 {
		part := &b.parts[keep]
		if int64(part.span.Len()) > remaining {
			part.span, _ = part.span.Slice(0, int(remaining))
			remaining = 0
		} else {
			remaining -= int64(part.span.Len())
		}
		keep++
	}
	clear(b.parts[keep:])
	b.parts = b.parts[:keep]
	b.len = m.offset
	// Discard the writable tail. Future writes use a fresh slab and can never
	// accidentally extend a descriptor over discarded or borrowed bytes.
	b.slab = nil
	b.used = 0
	b.currentPart = -1
}

internal/wire/cursor.go::Cursor.RequireE.Source:
func (c *Cursor) RequireEnd() error {
	if c.remaining != 0 {
		return ErrTrailingBytes
	}
	return nil
}

internal/wire/cursor.go::Cursor.Skip.Source:
func (c *Cursor) Skip(n int64) error {
	if err := c.check(n); err != nil {
		return err
	}
	c.advance(n)
	return nil
}

internal/wire/cursor.go::Cursor.Take.Source:
func (c *Cursor) Take(n int64) (Chain, error) {
	perfAdd(3, 1)
	if err := c.check(n); err != nil {
		return Chain{}, err
	}
	if n == 0 {
		return Chain{}, nil
	}
	// Capture the first descriptor and advance once in wire order. Constructing
	// a sequential range must not perform the random-access index search per cell.
	first, offset, base := c.index, c.offset, c.chain.base+c.chain.Len()-c.remaining
	head := c.chain.span(first)
	if n <= int64(head.Len()-offset) {
		head, _ = head.Slice(offset, int(n))
		c.advance(n)
		return Chain{head: head, len: n}, nil
	}
	head, _ = head.Slice(offset, head.Len()-offset)
	c.advance(n)
	last, lastLen := c.index, c.offset
	if lastLen == 0 {
		last--
		lastLen = c.chain.span(last).Len()
	}
	return Chain{head: head, tail: c.chain.tail[first:last], len: n,
		lastLen: lastLen, base: base}, nil
}

internal/wire/lease.go::.NewLease.Source:
func NewLease(chain Chain, release func()) *Lease {
	l := &Lease{chain: chain, release: release}
	perfLease(chain.Len())
	l.refs.Store(1)
	return l
}

internal/wire/lease.go::Lease.Release.Source:
func (l *Lease) Release() {
	if l == nil {
		return
	}
	for {
		n := l.refs.Load()
		if n <= 0 {
			return
		}
		if l.refs.CompareAndSwap(n, n-1) {
			perfAdd(8, 1)
			if n == 1 {
				perfLease(-l.chain.Len())
				if l.release != nil {
					l.release()
				}
			}
			return
		}
	}
}

internal/wire/lease.go::Lease.Retain.Source:
func (l *Lease) Retain() bool {
	if l == nil {
		return false
	}
	for {
		n := l.refs.Load()
		if n <= 0 || n == math.MaxInt64 {
			return false
		}
		if l.refs.CompareAndSwap(n, n+1) {
			perfAdd(7, 1)
			return true
		}
	}
}

internal/wire/receive_cache.go::ReceiveC.Source:
func (c *ReceiveCache) Release(b []byte, epoch uint64) {
	if c == nil || cap(b) > ReceiveCacheMaxObject || cap(b) == 0 {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed || epoch != c.epoch {
		return
	}
	// Keep the largest reusable frame classes under the same fixed session cap.
	// Inspect at most four slots; tiny metadata cannot starve data frame reuse.
	for len(c.entries) >= ReceiveCacheMaxObjects || cap(b) > ReceiveCacheMaxBytes-c.bytes {
		smallest := -1
		for i, v := range c.entries {
			if smallest < 0 || cap(v) < cap(c.entries[smallest]) {
				smallest = i
			}
		}
		if smallest < 0 || cap(c.entries[smallest]) >= cap(b) {
			return
		}
		c.bytes -= cap(c.entries[smallest])
		last := len(c.entries) - 1
		c.entries[smallest] = c.entries[last]
		c.entries[last] = nil
		c.entries = c.entries[:last]
	}
	c.entries = append(c.entries, b[:cap(b)])
	c.bytes += cap(b)
}

internal/wire/span.go::.NewChain.Source:
func NewChain(spans ...Span) (Chain, error) {
	var c Chain
	count := 0
	for _, s := range spans {
		perfAdd(0, 1)
		if s.Len() == 0 {
			continue
		}
		var err error
		c.len, err = addLength(c.len, s.Len())
		if err != nil {
			return Chain{}, err
		}
		count++
	}
	if count == 0 {
		return Chain{}, nil
	}
	if count > 1 {
		c.tail = make([]indexedSpan, count-1)
	}
	i := 0
	var end int64
	for _, s := range spans {
		perfAdd(0, 1)
		if s.Len() == 0 {
			continue
		}
		end += int64(s.Len())
		if i == 0 {
			c.head = s
		} else {
			c.tail[i-1] = indexedSpan{span: s, end: end}
		}
		i++
	}
	return c, nil
}

internal/wire/span.go::Chain.Slice.Source:
func (c Chain) Slice(off, n int64) (Chain, error) {
	if off < 0 || n < 0 || off > c.len || n > c.len-off {
		return Chain{}, ErrBounds
	}
	if n == 0 {
		return Chain{}, nil
	}
	if off == 0 && n == c.len {
		return c, nil
	}
	first := c.locate(off)
	last := c.locate(off + n - 1)
	start := int64(0)
	if first == 1 {
		start = int64(c.head.Len())
	} else if first > 1 {
		start = c.tail[first-2].end - c.base
	}
	head := c.span(first)
	skip := off - start
	if first == last {
		s, _ := head.Slice(int(skip), int(n))
		return Chain{head: s, len: n}, nil
	}
	head, _ = head.Slice(int(skip), head.Len()-int(skip))
	lastStart := int64(c.head.Len())
	if last > 1 {
		lastStart = c.tail[last-2].end - c.base
	}
	return Chain{head: head, tail: c.tail[first:last], len: n,
		lastLen: int(off + n - lastStart), base: c.base + off}, nil
}

internal/wire/span.go::Span.Slice.Source:
func (s Span) Slice(off, n int) (Span, error) {
	if off < 0 || n < 0 || off > len(s.data) || n > len(s.data)-off {
		return Span{}, ErrBounds
	}
	return Span{data: s.data[off : off+n : off+n]}, nil
}

internal/wire/stream.go::.CheckProduct.Source:
func CheckProduct(a, b, limit int64) (int64, error) {
	if a < 0 || b < 0 || limit < 0 {
		return 0, ErrLength
	}
	if b != 0 && a > limit/b {
		return 0, ErrLimit
	}
	return a * b, nil
}

internal/wire/stream.go::Stream.Cell.Source:
func (s *Stream) Cell(allowUnset bool, fn func(CellState, *Stream) error) error {
	v, err := s.Uint32()
	if err != nil {
		return err
	}
	n := int64(int32(v))
	state := CellPresent
	if n == -1 {
		state, n = CellNull, 0
	} else if n == -2 && allowUnset {
		state, n = CellUnset, 0
	} else if n < 0 {
		return s.fail(ErrLength)
	}
	if fn == nil {
		return s.fail(ErrStreamScope)
	}
	return s.Child(n, func(child *Stream) error { return fn(state, child) })
}

internal/wire/stream.go::Stream.Count32.Source:
func (s *Stream) Count32(minBytes int64) (int64, error) {
	if minBytes < 0 {
		return 0, s.fail(ErrLength)
	}
	v, err := s.Uint32()
	if err != nil {
		return 0, err
	}
	n := int64(int32(v))
	if n < 0 {
		return 0, s.fail(ErrLength)
	}
	if n > s.state.limits.MaxCount || (minBytes > 0 && n > s.remaining/minBytes) {
		return 0, s.fail(ErrLimit)
	}
	return n, nil
}

internal/wire/stream.go::Stream.RequireE.Source:
func (s *Stream) RequireEnd() error {
	if err := s.check(); err != nil {
		return err
	}
	if s.remaining != 0 {
		return s.fail(ErrTrailingBytes)
	}
	return nil
}

internal/wire/stream.go::Stream.Skip.Source:
func (s *Stream) Skip() error {
	if err := s.check(); err != nil {
		return err
	}
	if s.remaining == 0 {
		return nil
	}
	if s.state.discard == nil {
		s.state.discard = make([]byte, min(int64(s.state.limits.DiscardBytes), s.state.limits.MaxBytes))
	}
	for s.remaining > 0 {
		p := s.state.discard[:min(int64(len(s.state.discard)), s.remaining)]
		if err := s.ReadFull(p); err != nil {
			return err
		}
	}
	return nil
}

internal/wirecompress/frame_limit.go::.F.Source:
func FrameDecoderWithLimit(c interface{ Name() string }, limit int64) (FrameDecoder, bool) {
	switch c.(type) {
	case LZ4Compressor, *LZ4Compressor:
		return FrameDecoder{limit: limit}, true
	case SnappyCompressor, *SnappyCompressor:
		return FrameDecoder{limit: limit, snappy: true}, true
	default:
		decoder, ok := c.(frameOutputDecoder)
		return FrameDecoder{custom: decoder}, ok
	}
}

internal/wirecompress/frame_limit.go::Fr.Source:
func (d FrameDecoder) DecodeTo(dst, data []byte) ([]byte, error) {
	if d.custom != nil {
		return d.custom.DecodeTo(dst, data)
	}
	n, err := d.DecodedLen(data)
	if err != nil {
		return nil, err
	}
	if d.snappy {
		return s2.Decode(dst[:0], data)
	}
	if n == 0 {
		return dst[:0], nil
	}
	out, err := appendLZ4Decompressed(dst[:0], data[dataLengthSize:], n)
	if err == nil && len(out) != n {
		err = fmt.Errorf("gocql: decoded frame length %d differs from declared %d", len(out), n)
	}
	return out, err
}

func (d FrameDecoder) DecodedLen(data []byte) (int, error) {
	if d.custom != nil {
		return d.custom.DecodedLen(data)
	}
	var size int64
	if d.snappy {
		n, err := s2.DecodedLen(data)
		if err != nil {
			return 0, err
		}
		size = int64(n)
	} else {
		if len(data) < dataLengthSize {
			return 0, fmt.Errorf("cassandra lz4 block size should be >4, got=%d", len(data))
		}
		size = int64(binary.BigEndian.Uint32(data))
	}
	// Native lengths are signed int32. Check before int conversion, output
	// acquisition or decoder allocation, including on 32-bit platforms.
	if size > d.limit || size > math.MaxInt32 || d.limit <= 0 {
		return 0, fmt.Errorf("gocql: decompressed frame length %d exceeds maximum of %d", size, min(d.limit, math.MaxInt32))
	}
	return int(size), nil
}

internal/wirecompress/lz4.go::LZ4Compres.Source:
func (s LZ4Compressor) DecodeTo(dst, data []byte) ([]byte, error) {
	n, e := s.DecodedLen(data)
	if e != nil {
		return nil, e
	}
	if n == 0 {
		return dst[:0], nil
	}
	return s.AppendDecompressed(dst[:0], data[dataLengthSize:], uint32(n))
}

func (s LZ4Compressor) DecodedLen(data []byte) (int, error) {
	if len(data) < dataLengthSize {
		return 0, fmt.Errorf("cassandra lz4 block size should be >4, got=%d", len(data))
	}
	uncompressedLength := binary.BigEndian.Uint32(data[:dataLengthSize])
	if uncompressedLength == 0 {
		return 0, nil
	}
	if uncompressedLength > maxDecompressedSize {
		return 0, fmt.Errorf("cassandra lz4 uncompressed length %d exceeds maximum of %d", uncompressedLength, maxDecompressedSize)
	}
	return int(uncompressedLength), nil
}

internal/wirecompress/snappy_frame.go::S.Source:
func (s SnappyCompressor) DecodeTo(dst, data []byte) ([]byte, error) {
	if _, e := s.DecodedLen(data); e != nil {
		return nil, e
	}
	return s2.Decode(dst[:0], data)
}

func (s SnappyCompressor) DecodedLen(data []byte) (int, error) {
	// s2.Decode allocates the decoded block from the length varint at the head of
	// data -- a length the peer declared, which s2 itself only refuses above 4 GiB.
	// The frame reader bounds the *compressed* body it accepts against
	// frm.MaxFrameSize, but nothing bounds what that body expands into, so a few
	// corrupt header bytes on a short frame are enough to ask for a multi-gigabyte
	// allocation.
	//
	// frm.MaxFrameSize is reused as the ceiling, but that is a driver-side trade
	// rather than a protocol fact. At v4 the header length, and the server's
	// native_transport_max_frame_size, both bound the *compressed* body, so a
	// legitimate frame may carry a body within that limit which decodes above it.
	// Refusing those gives up a case nobody has reported -- a response compressing
	// to under 256 MiB and expanding past it -- in exchange for bounding an
	// allocation whose size the peer controls. LZ4Compressor makes the same trade
	// with maxDecompressedSize in this package.
	//
	// s2.DecodedLen reads the same varint without allocating, so this costs a few
	// bytes of parsing rather than a second pass.
	//
	// The 32-bit hazard lz4's comment cites does not apply here: above MaxInt32 s2
	// already returns ErrTooLarge rather than panicking in makeslice.
	n, err := s2.DecodedLen(data)
	if err != nil {
		return 0, err
	}
	if n > frm.MaxFrameSize {
		return 0, fmt.Errorf("gocql: snappy uncompressed length %d exceeds maximum of %d", n, frm.MaxFrameSize)
	}

	return n, nil
}
